package com.healthdiary.app.data.local

object SeedData {
    suspend fun seedIfEmpty(db: AppDatabase) {
        if (db.exerciseLibraryDao().count() == 0) {
            db.exerciseLibraryDao().insertAll(EXERCISES)
        }
        if (db.foodLibraryDao().count() == 0) {
            db.foodLibraryDao().insertAll(FOODS)
        }
    }

    /** 老用户升级后补齐食物库中缺失的条目（按名称去重，不覆盖已有数据） */
    suspend fun ensureFoodLibraryComplete(db: AppDatabase) {
        val existing = db.foodLibraryDao().getAll().map { it.name }.toHashSet()
        val missing = FOODS.filter { it.name !in existing }
        if (missing.isNotEmpty()) {
            db.foodLibraryDao().insertAll(missing)
        }
    }

